/**
 * ignis-platform.js — IGNIS Platform Intelligence Panel
 *
 * DESTINATION: VaultSparkStudios.github.io/assets/ignis-platform.js
 *
 * How to apply:
 *   cp docs/WEBSITE_INTEGRATION/ignis-platform.js \
 *      ../VaultSparkStudios.github.io/assets/ignis-platform.js
 *
 * Then add to ignis/index.html before </body>:
 *   <script src="/assets/ignis-platform.js" defer></script>
 *
 * Reads: /api/ignis-platform-status.json (generated by build-ignis-platform-status.mjs)
 * Populates: elements with data-ignis-* attributes on the IGNIS page
 *
 * Data-bind attributes:
 *   data-ignis-sil        → SIL score (e.g. "948")
 *   data-ignis-sil-pct    → SIL percentage (e.g. "94.8%")
 *   data-ignis-sil-trend  → trend arrow (↑ ↓ →)
 *   data-ignis-intel      → intelligence health percentage (e.g. "78%")
 *   data-ignis-sessions   → total session count (e.g. "186")
 *   data-ignis-status     → status text (e.g. "All systems operational")
 *   data-ignis-status-dot → status badge class (green/yellow/red)
 *   data-ignis-voice      → public voice summary paragraph
 *   data-ignis-sparkline  → container to receive a sparkline bar chart
 *   data-ignis-caps       → container to receive capability cards
 */

(function () {
  'use strict';

  var API_URL  = '/api/ignis-platform-status.json';
  var CACHE_MS = 10 * 60 * 1000; // 10 minutes

  var STATUS_COLORS = {
    green:  '#22c55e',
    yellow: '#eab308',
    red:    '#ef4444',
  };

  function $(sel, ctx) { return (ctx || document).querySelector(sel); }
  function $$(sel, ctx) { return Array.prototype.slice.call((ctx || document).querySelectorAll(sel)); }

  function loadData(cb) {
    var cacheKey = 'ignis_platform_cache';
    var tsKey    = 'ignis_platform_ts';
    try {
      var cached = localStorage.getItem(cacheKey);
      var ts     = parseInt(localStorage.getItem(tsKey) || '0', 10);
      if (cached && Date.now() - ts < CACHE_MS) {
        return cb(null, JSON.parse(cached));
      }
    } catch (_) {}

    var xhr = new XMLHttpRequest();
    xhr.open('GET', API_URL);
    xhr.onload = function () {
      if (xhr.status !== 200) return cb(new Error('HTTP ' + xhr.status));
      try {
        var data = JSON.parse(xhr.responseText);
        try {
          localStorage.setItem(cacheKey, xhr.responseText);
          localStorage.setItem(tsKey, String(Date.now()));
        } catch (_) {}
        cb(null, data);
      } catch (e) {
        cb(e);
      }
    };
    xhr.onerror = function () { cb(new Error('Network error')); };
    xhr.send();
  }

  function setText(sel, val) {
    $$('[data-ignis-' + sel + ']').forEach(function (el) {
      el.textContent = val != null ? String(val) : '—';
    });
  }

  function buildSparkline(container, sparkline) {
    if (!sparkline || !sparkline.length) return;
    var max = Math.max.apply(null, sparkline);
    var min = Math.min.apply(null, sparkline);
    var range = max - min || 1;

    container.innerHTML = '';
    var wrap = document.createElement('div');
    wrap.style.cssText = 'display:flex;align-items:flex-end;gap:3px;height:36px;';

    sparkline.forEach(function (val) {
      var bar = document.createElement('div');
      var pct = Math.max(8, Math.round(((val - min) / range) * 100));
      bar.style.cssText = 'flex:1;border-radius:2px 2px 0 0;background:linear-gradient(180deg,#FF7A00,#FFC400);min-width:4px;';
      bar.style.height = pct + '%';
      bar.title = String(val);
      wrap.appendChild(bar);
    });

    container.appendChild(wrap);
  }

  function buildCapabilities(container, caps) {
    if (!caps || !caps.length) return;
    container.innerHTML = '';
    caps.forEach(function (cap) {
      var card = document.createElement('div');
      card.className = 'ignis-cap-card';
      card.innerHTML =
        '<strong>' + escHtml(cap.label) + '</strong>' +
        '<span>' + escHtml(cap.detail || '') + '</span>';
      container.appendChild(card);
    });
  }

  function escHtml(str) {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function hydrate(data) {
    if (!data || data._placeholder) return;

    // SIL metrics
    var sil = data.sil || {};
    setText('sil', sil.score != null ? String(sil.score) : null);
    setText('sil-pct', sil.pct != null ? sil.pct + '%' : null);
    setText('sil-trend', sil.trend || '→');
    setText('sil-max', sil.max != null ? '/' + sil.max : '/1000');

    // Intelligence health
    var intel = data.intelligence || {};
    setText('intel', intel.health != null ? intel.health + '%' : null);
    setText('intel-pct', intel.healthPct != null ? intel.healthPct + '%' : null);

    // Sessions
    var sessions = data.sessions || {};
    setText('sessions', sessions.total);
    setText('ships-avg', sessions.avgShipsPerSession != null
      ? sessions.avgShipsPerSession + ' ships/session' : null);
    setText('test-rate', sessions.testPassRate != null
      ? sessions.testPassRate + '%' : null);

    // Platform status
    setText('status', data.statusLabel || data.status || '—');
    $$('[data-ignis-status-dot]').forEach(function (el) {
      var color = STATUS_COLORS[data.status] || '#94a3b8';
      el.style.background = color;
      el.style.boxShadow  = '0 0 8px ' + color;
    });

    // Voice summary
    setText('voice', data.voice || null);

    // Sparkline
    $$('[data-ignis-sparkline]').forEach(function (el) {
      buildSparkline(el, sil.sparkline);
    });

    // Capabilities
    $$('[data-ignis-caps]').forEach(function (el) {
      buildCapabilities(el, data.capabilities);
    });

    // Show platform panel if hidden
    $$('[data-ignis-platform-panel]').forEach(function (el) {
      el.style.display = '';
      el.setAttribute('aria-hidden', 'false');
    });
  }

  function init() {
    loadData(function (err, data) {
      if (err) {
        console.warn('ignis-platform: failed to load data', err);
        return;
      }
      hydrate(data);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
